const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Singapore' }));
const todayDay = now.getDate();
const thisMonth = now.getMonth();
const thisYear = now.getFullYear();

const rows = $input.all().map(i => i.json);

const due = rows.filter(row => {
  if (!row['Employer Name']) return false;
  const payDay = parseInt(row['Payment Due Day']);
  if (isNaN(payDay) || payDay !== todayDay) return false;

  // Check if end date has passed
  const endDate = row['End Date'];
  if (endDate) {
    const end = new Date(endDate);
    if (!isNaN(end) && now >= end) return false;
  }

  // Check if already paid this month
  const lastPaid = row['Last Paid Date'];
  if (lastPaid) {
    const paidDate = new Date(lastPaid);
    if (!isNaN(paidDate) && paidDate.getMonth() === thisMonth && paidDate.getFullYear() === thisYear) {
      return false; // already paid this month
    }
  }
  return true;
});

const today = now.toLocaleDateString('en-SG', { day: 'numeric', month: 'long', year: 'numeric' });

return [{ json: {
  hasDue: due.length > 0,
  count: due.length,
  today,
  items: due.map(r => ({
    employer: r['Employer Name'] || '',
    maid: r['Maid Name'] || '',
    salary: r['Salary Amount'] || '',
    payDay: r['Payment Due Day'] || '',
    notes: r['Notes'] || ''
  }))
} }];
